      ...(source.portraitizer || {}),
      status: fallbackCards.length ? 'partial_reference_cards_source_photo_fallback' : (readyCards.length ? 'hero_reference_cards_ready' : 'generating_combined_reference_sheet'),
      architecture: 'per_hero_style_native_identity_map_reference_cards_v2',
      heroReferenceCardCount: readyCards.length,
      sourcePhotoFallbackCount: fallbackCards.length,
      cards: heroReferenceCards.map(({ contentBase64, prompt, ...card }) => card),
    },
    geminiPortraitRequest,
  },
}];
